-- workspaces.lua - Dynamically loads workspaces.conf generated by nwg-displays
---@module 'hl'

local home = os.getenv("HOME") or "/home/dante"
local conf_path = home .. "/.config/hypr/workspaces.conf"

local f = io.open(conf_path, "r")
if f then
    for raw_line in f:lines() do
        local l = raw_line:gsub("#.*", ""):match("^%s*(.-)%s*$")
        if l and l:match("^workspace%s*=") then
            local val = l:match("^workspace%s*=%s*(.*)$")
            if val and #val > 0 then
                local parts = {}
                for part in val:gmatch("([^,]+)") do
                    table.insert(parts, part:match("^%s*(.-)%s*$"))
                end
                if #parts >= 1 then
                    local ws_id = tonumber(parts[1]) or parts[1]
                    local rule = { workspace = ws_id }
                    for i = 2, #parts do
                        local opt = parts[i]
                        if opt:match("^monitor:(.+)") then
                            rule.monitor = opt:match("^monitor:(.+)")
                        elseif opt:match("^default:(.+)") then
                            rule.default = (opt:match("^default:(.+)") == "true")
                        elseif opt:match("^gapsin:(.+)") then
                            rule.gaps_in = tonumber(opt:match("^gapsin:(.+)"))
                        elseif opt:match("^gapsout:(.+)") then
                            rule.gaps_out = tonumber(opt:match("^gapsout:(.+)"))
                        end
                    end
                    hl.workspace_rule(rule)
                end
            end
        end
    end
    f:close()
end
